-- Generated by release/build_faq.py from the plugin developer Discord research
-- (discord-dev-faq.md). Do not edit by hand.
return {
    { n = 1, q = "requiredPermissions isn't working (trackingAccess, httpAccess, chatAccess)", a = "Put permissions in optionalPermissions, leave requiredPermissions empty, then grant them from the console. Zippilipy: \"requiredPermissions\": [ ], \"optionalPermissions\": [ \"trackingAccess\" ], Mod/known issue (Friendliness): \"requiredPermissions\" doesn't currently work, if you need something like chatAccess put it in \"optionalPermissions\"", freq = "Often (4+ askers on Oct 19, again Oct 20). Also a known issue.", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19; #api-launch-known-issues, Oct 19.", code = { "\"requiredPermissions\": [ ], \"optionalPermissions\": [ \"trackingAccess\" ],", "\"requiredPermissions\" doesn't currently work, if you need something like chatAccess put it in \"optionalPermissions\"" } },
    { n = 2, q = "How do I grant a permission such as httpAccess in dev? ppe prints nothing.", a = "Run prf or restart the client after editing the manifest, then run these in order: ppr pluginname ppe pluginname httpAccess prl pluginname A user's explanation: \"prl is conditional to plugin needs but habitual depending on usage, ppr is needed to initialize the permissions until the permission popups are live.\" Another user's note: \"The plugin permissions prompt will come in the future which will remove the ppr + ppe needs in the console at least.\"", freq = "Several (Oct 19, Oct 19 evening).", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19.", code = { "ppr pluginname ppe pluginname httpAccess prl pluginname" } },
    { n = 3, q = "How do I stop re-typing the permission commands every reload?", a = "Zippilipy: put them in main.lua so they run each load.", freq = "Once.", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19.", code = { "ExecuteConsoleCommand(\"ppr pluginname\")", "ExecuteConsoleCommand(\"ppe pluginname trackingAccess\")" } },
    { n = 4, q = "plugin.json changes aren't picked up / permissions still failing", a = "\"run prf if you change the plugin manifest at all\". Some users restart the client instead.", freq = "Several.", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19; Oct 19 evening.", code = {  } },
    { n = 5, q = "Manifest won't load because of a JSON syntax error", a = "JosTheFarmer: \"Remove the last comma after urls. Json does not like trailing commas\".", freq = "Once, but a common cause.", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19, 10:31 AM.", code = { "{ \"name\": \"name\", \"version\": \"0.0.1\", \"contactEmailAddress\": \"*\", \"requiredPermissions\": [], \"optionalPermissions\": [ \"httpAccess\" ], \"urls\": { \"discord\" : \"https://discord.com\" }, }" } },
    { n = 6, q = "Can I reload my plugin without restarting the client? What do prf and prl do?", a = "Saving the file and running prl pluginname reloads it: \"Just save the file, prl plogon and bam\". Double-clicking the plugin's checkbox in the plugin menu also reloads it. Use prf after manifest changes. Up arrow in the console recalls earlier commands. Open the console with alt + (backtick). displayfps shows FPS for performance testing.", freq = "Often.", section = "A. plugin.json, permissions, reloading, debugging", where = "#general-technical, Oct 19; #plugin-support, Oct 19.", code = { "prl pluginname", "prf", "displayfps" } },
    { n = 7, q = "Is there an event for the plugin enable/disable button? I need to clean up when it's disabled.", a = "The button only triggers the startup/shutdown lifecycle hooks (PluginShutdown). Docs: https://developer.runescape.com/rs/core/clientoptions.html?h=pluginShutdown#example. Example given: disable login-screen music while the plugin is active, then restore it on shutdown.", freq = "Once.", section = "A. plugin.json, permissions, reloading, debugging", where = "#general-technical, Oct 20.", code = {  } },
    { n = 8, q = "Dependency error: \"Failed to resolve dependencies. Missing dependency rsprite for plugin\"", a = "Review the manifest structure: https://developer.runescape.com/rs/structure.html#manifest. The asker also had to check they used the rsprite release rather than the whole repo. No definitive fix posted.", freq = "Once.", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 21.", code = {  } },
    { n = 9, q = "Can I depend on another plugin by name, or only by mod.io ID?", a = "A string name works only for local dev, with the plugin in the plugins folder: { \"zyklib\": \"zyklib\" }. For submission it must be the mod.io ID: { \"zyklib\": 123456 }. Dependencies are globals named by the dependency key, so you do not require them.", freq = "Several (zyklib thread).", section = "A. plugin.json, permissions, reloading, debugging", where = "#general-technical, Oct 20.", code = {  } },
    { n = 10, q = "Does contactEmailAddress have to be in plugin.json? Can I keep it out of the public listing?", a = "No exemption was offered. Docs say: \"A contact email by which a user of the plugin can reach the creator. This is a legal requirement, and it is recommended to be different to the email address used to access your Mod.io account.\" Advice from other devs: make a dedicated plugin email and forward it. Jagex uses it if you go AWOL and need to fix something.", freq = "Once.", section = "A. plugin.json, permissions, reloading, debugging", where = "#general-technical, Oct 21.", code = {  } },
    { n = 11, q = "My plugin turns itself off when I lobby, change world or log in. How do I test re-enable on login?", a = "\"not in dev, only installed plugins via mod.io re-enable on login\". The Job Gauges disable-on-login was a plugin bug (error on first load, no ammo sprite) and is fixed in an upcoming version.", freq = "Several (also Job Gauges disabling on login).", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19-22.", code = {  } },
    { n = 12, q = "Dev client and main client share installed plugins and settings. Is there a fix?", a = "No fix yet. Installed plugin files are shared by every client on the PC, and plugin settings are stored locally, so two accounts or a dev and a main client see the same plugins and settings. Updating plugins by hand while several clients are open can crash the other clients; Jagex staff called this an important issue and passed it on. Saving settings per account is up to each plugin: a plugin can request permission to an account identifier and key its saved data on it. Many early plugins use one shared set of settings or preset import and export instead.", freq = "Several.", section = "A. plugin.json, permissions, reloading, debugging", where = "#plugin-support, Oct 19-20; #general-technical, Oct 21. Updated Oct 23 (#plugin-support, staff reply; #general-technical, community answer).", code = {  } },
    { n = 42, q = "Can a plugin have more than one .lua file?", a = "Yes. Several plugins already split their code, for example keeping constants in their own file and loading it from main.lua with require. Quest Helper's source is a good example layout: https://codeberg.org/QuestHelper/QuestHelper/src/branch/main/src", freq = "Once.", section = "A. plugin.json, permissions, reloading, debugging", where = "#dev-questions, Oct 23 (community answer).", code = {  } },
    { n = 13, q = "Error: \"Failed to Create Layer (category=0 ID=4096) - invalid dynamic ID, expected a value between 0 and 4096\"", a = "Components aren't being cleaned up. Check the \"Valid ID Ranges\" panel at https://developer.runescape.com/rs/ui/index.html?h=4096#components. Call layer:DeleteAll() before a rebuild. The game destroys components YOUR plugin creates on reload or shutdown, but not components PrettyUI creates. So make your own empty layer, pass it to PrettyUI as the root, and call mainWindow:Destroy() in PluginShutdown. Also prefer mounting on TOPLEVEL_V2__PLUGIN_BUILD_LAYER_TOP or TOPLEVEL_V2__PLUGIN_BUILD_LAYER_BOTTOM instead of TOPLEVEL_V2__GAME_AREA. The reporter's fix was to destroy the SimpleView in PluginShutdown.", freq = "Several (noted as seen before).", section = "B. UI and PrettyUI", where = "#general-technical, Oct 21.", code = { "layer:DeleteAll()", "mainWindow:Destroy()", "PluginShutdown", "TOPLEVEL_V2__PLUGIN_BUILD_LAYER_TOP", "TOPLEVEL_V2__PLUGIN_BUILD_LAYER_BOTTOM", "TOPLEVEL_V2__GAME_AREA" } },
    { n = 14, q = "How do I create a headerless group box? SetHeaderLayout(0,0,0,0,0) still shows a header.", a = "No fix posted. Others confirmed the same behavior, so it's an API or tutorial issue. The related tutorial-typo question (strayDogName vs strayDogConfig.name) was answered \"Probably just a mistake, no reason not to\".", freq = "Several (3 reports incl. at 1440p, so not a resolution issue).", section = "B. UI and PrettyUI", where = "#plugin-support, Oct 19.", code = {  } },
    { n = 15, q = "Drag/move and drag-and-drop break on 2K/4K/QHD or high-DPI monitors (Job Gauges)", a = "Reported coordinates scale by 2x/4x pixel density, so components don't follow the mouse 1:1. PrettyUI fixed this. Look at PrettyUI's InterfaceMouse. It works by calculating how far something has moved once dragging begins, and Zammy BLM uses it. One dev's custom workaround: track the hovered component on drop instead of using the native drag start/stop positions.", freq = "Several.", section = "B. UI and PrettyUI", where = "#plugin-support, Oct 19; #general-technical, Oct 22.", code = { "InterfaceMouse" } },
    { n = 16, q = "Can I auto-focus a text input after a hotkey press?", a = "Not currently possible. The poster has a feature request in.", freq = "Once.", section = "B. UI and PrettyUI", where = "#general-technical, Oct 22.", code = {  } },
    { n = 17, q = "What is the \"value\" param for PrettyUI CheckboxButton?", a = "It is the value your callback receives for that checkbox, so it works like a label: when several checkboxes share one callback you can tell which one changed. If a value is set it is passed when the box is ticked; otherwise you read the box's ticked state. It is mostly used for defaults, and lets a group of checkboxes behave like radio buttons that allow more than one choice.", freq = "Once.", section = "B. UI and PrettyUI", where = "#plugin-support, Oct 20. Updated Oct 21 (community answer).", code = {  } },
    { n = 18, q = "Can I make a PrettyUI window transparent but still movable (show only sprites)?", a = "You can take the PrettyUI window's root component and change its properties (for example its background) yourself. If you only need sprites, a simpler route is to draw native sprites in a native panel, or use the rsprite library.", freq = "Once.", section = "B. UI and PrettyUI", where = "#plugin-support, Oct 22. Updated Oct 22 (community answer).", code = {  } },
    { n = 19, q = "ui.Interfaces:GetComponent() returns the previous clue-scroll text, not the current text", a = "InventoryAdded fires before the server has filled in the reward text, so reading the component then gives the previous value. A working pattern: in InventoryAdded or InventoryUpdated set a flag; subscribe to the modal's ui.Hook.ONSUBCHANGE and mark the interface ready there; then, on the next Event.Logic tick, read id.Component.TRAIL_REWARD__CURRENT_VALUE and Inventory.Find(id.Inv.TRAIL_REWARDINV). The asker confirmed this works. For prices, a GE price library gives more accurate values.", freq = "Once, long thread.", section = "B. UI and PrettyUI", where = "#general-technical, Oct 21. Updated Oct 21 (community answer, confirmed working).", code = {  } },
    { n = 20, q = "Why are chat event fields read-only? Can I modify chat?", a = "Chat isn't writable. You can hide messages and rewrite them through the plugin chat type, and this needs chatAccess. Setting content to an empty string leaves a blank line, and nil doesn't work. Related: Chat.AddMessage messages vanish when a friend logs in or out. That was asked, with no answer found.", freq = "Once.", section = "B. UI and PrettyUI", where = "#general-technical, Oct 19.", code = { "chatAccess", "Chat.AddMessage" } },
    { n = 21, q = "Two listeners on Event.NPCEntityAdded: only the first gets usable data (isValid=false, name nil)", a = "Reported in game as a bug. A dev suggested trying a return value in the handler, but \"most events dont care about return values\". EntityDraw docs require a return value, and the docs should say whether a return is required for others. Not resolved.", freq = "Once, with multiple confirmers.", section = "C. API usage and events", where = "#plugin-support, Oct 20.", code = {  } },
    { n = 22, q = "No os library. How do I time something (stopwatch)?", a = "\"There's no os atm so you'd need to use logictick\".", freq = "Once.", section = "C. API usage and events", where = "#general-technical, Oct 22.", code = {  } },
    { n = 23, q = "Property named valid in the docs is actually isValid", a = "Docs bug: https://developer.runescape.com/rs/game/inventory.html#properties. Report it as a documentation issue.", freq = "Once (docs bug).", section = "C. API usage and events", where = "#plugin-support, Oct 19.", code = {  } },
    { n = 24, q = "What the API can't do yet (feature-gap questions)", a = "Player animations can't be swapped: \"Not available yet\". Drop tables are server-side, so use wiki data in a static Lua file. There is no direct kill-to-drop link. Item perks on gizmos/augmented gear aren't exposed. Rockertunity spawns aren't detectable. The sparkle is spotanim 7165, which plays over every rock, and spotanim API support is incomplete. LocList.All() returns only scenery, not walls, roofs or ground decorations. Collision data isn't reliably exposed. Friends and FC lists are only readable while their window is active. Action bars can't be modified: \"Any movement or resizing of click zones...\" is restricted. Menu Entry Swapper restrictions are intentional (API restriction): no Buy All, and no default left-click Teleport/Drop. There is an open suggestion to prefix the stub types.", freq = "Often.", section = "C. API usage and events", where = "#plugin-support / #general-technical, Oct 19-22.", code = { "LocList.All()" } },
    { n = 25, q = "Is there Lua IntelliSense / SDK support in VS Code?", a = "Use the community stubs at https://github.com/FriendlyDevelopment/runescape-api-stubs/. Install a Lua extension (LuaLS). Put a .luarc.json in the opened plugin folder, adjusting the stub path if it's inside the workspace: Make sure the plugin's folder is the opened workspace.", freq = "Several.", section = "C. API usage and events", where = "#plugin-support, Oct 19-20.", code = { ".luarc.json", "{ \"$schema\": \"https://raw.githubusercontent.com/LuaLS/vscode-lua/master/setting/schema.json\", \"workspace.library\": [ \"../runescape-api-stubs/types.lua\", \"../runescape-api-stubs/generated/\" ], \"workspace.checkThirdParty\": false }" } },
    { n = 26, q = "Is there a base64 / shared utility library? How do I share libraries between plugins?", a = "zyklib (https://codeberg.org/ZyklopMarco/runescape-api-zyklib, docs at zyklib.readthedocs.io) was in review. The author considers static inclusion (copy into your plugin) safer than a dynamic dependency, because dynamic dependencies can't break backward compatibility. See #9 for how to depend on it.", freq = "Several.", section = "C. API usage and events", where = "#general-technical, Oct 20.", code = {  } },
    { n = 27, q = "Which components are allowed in the API vs. cheat commands (getVar, getvarc)?", a = "Cheats don't work on live (https://developer.runescape.com/rs/cheats.html?h=getVar#getvar). Reading hidden client information (e.g. herb patch state when not nearby) wouldn't be approved. Reading loc data is allowed. !getvarc returned an unknown-cheat error, and no answer was posted.", freq = "Several.", section = "C. API usage and events", where = "#general-technical, Oct 20-22.", code = { "!getvarc" } },
    { n = 41, q = "Messages added with Chat.AddMessage disappear when a friend logs in or out", a = "Known to others but with no fix: it may or may not be intended. Re-add important messages if they must stay visible.", freq = "Once.", section = "C. API usage and events", where = "#plugin-support, Oct 21 (community answer, partial).", code = {  } },
    { n = 43, q = "How do I link a Construction furniture item to its object (loc), e.g. Trellis?", a = "Through DBRows: find the row in the construction_house_furniture table whose column 4 is the item, then read column 2 (config.DBRow.INVENT_PERK_LOOTING:GetColumnValues(2) shows the call style) for the loc (the loc links back to the row too). Column numbers are not guaranteed to stay the same across game updates, so check them after updates. Docs: https://developer.runescape.com/rs/game/config/dbrowtype.html", freq = "Once.", section = "C. API usage and events", where = "#dev-questions, Oct 21 (community answer).", code = {  } },
    { n = 44, q = "What is DBTableType for, if I already have DBRows?", a = "A DBTable defines the structure; DBRows are the entries in it. You usually only need DBRows. Use the table when you want column types or the default value for a column a row does not set.", freq = "Once.", section = "C. API usage and events", where = "#dev-questions, Oct 21 (community answer).", code = {  } },
    { n = 28, q = "Sound alert volume below 1 is rounded and the sound doesn't play", a = "Reported behaviour: \"for sound alerts seems any float value below 1 is being rounded down which disables the sound so it only works if float is set to 1\". No official fix posted. A related post covered the game.options volume settings (audio sliders live in game.options) and showed a sample that mutes login-screen music for the life of a plugin. Users also asked for sound options to return in Job Gauges.", freq = "Once.", section = "D. Sound", where = "#plugin-support, Oct 19-20; #general-technical, Oct 20.", code = {  } },
    { n = 29, q = "How do I register my plugin / reserve its name and mod.io ID in the directory?", a = "Use the Friendlybot commands in the server: /plugin signup: adds your plugin to the directory. /plugin team add: adds a team member. /plugin modio set: sets your mod.io ID. Management: /plugin rename, /plugin transfer, /plugin list, /plugin delete, /plugin modio remove, /plugin team leave, /plugin team remove. Signing up restricts the plugin name and mod.io ID to you.", freq = "Once (pinned how-to).", section = "E. Packaging, mod.io, submission, directory", where = "#plugin-directory-how-to, Oct 19.", code = { "/plugin signup", "/plugin team add", "/plugin modio set", "/plugin rename", "/plugin transfer", "/plugin list", "/plugin delete", "/plugin modio remove", "/plugin team leave", "/plugin team remove" } },
    { n = 30, q = "mod.io / Plugin Hub activation code email never arrives", a = "Retry, and check spam. If it still does not arrive, use a different email provider: the address does not have to be the one on your RuneScape account, and another provider worked straight away for one user. The known issues list says an email with a + sign can crash the Plugin Hub.", freq = "Several (2+ users; one on a 4th attempt).", section = "E. Packaging, mod.io, submission, directory", where = "#general-technical, Oct 19-20; #api-launch-known-issues, Oct 19. Updated Oct 21 (community answer).", code = {  } },
    { n = 31, q = "How do I test a plugin before it's on mod.io? Can plugin info be user-configured (e.g. self-hosted API base URL)?", a = "Self-hosting: probably not allowed, but \"that's one for Jewel\" (a mod). The author uses a fixed base URL in the manifest. Submitted plugins wait for Jagex review. Plugin updates were also awaiting review.", freq = "Once (self-host); the other is covered in #9.", section = "E. Packaging, mod.io, submission, directory", where = "#general-technical, Oct 20; #plugin-support, Oct 19.", code = {  } },
    { n = 32, q = "AI / LLM policy: can LLMs be given the docs?", a = "The docs said no, but staff (Grynjolf) said \"That might be holdover from before we went public\" and \"Policy will be updated\". Devs also said to check generated code before publishing.", freq = "Several (many participants).", section = "E. Packaging, mod.io, submission, directory", where = "#plugin-support, Oct 19.", code = {  } },
    { n = 45, q = "Will plugins that store data on a shared server be approved?", a = "No plan has been announced yet. It is likely possible, but sending data off the PC brings the data protection rules into play (endpoints, security measures, and the UK adequacy page: https://developer.runescape.com/rs/submission/adequacy.html).", freq = "Once.", section = "E. Packaging, mod.io, submission, directory", where = "#dev-questions, Oct 21 (community answer, not official).", code = {  } },
    { n = 33, q = "Cheat commands (!give, teleport, getvar) don't work on dev/beta worlds", a = "Known issue: \"Cheat Commands on developer worlds are not working as intended. We're investigating... (no ETA)\". The docs warn that cheats are logged and abuse can lead to bans. Community guidance on scope: don't spawn hidden or future items, or spam items. Example workaround when working: !setgroupironman 1 sets account type for testing shared bank. A dev script was shared to print the cheat commands needed to complete an achievement.", freq = "Often (6+).", section = "F. Cheats and the dev environment", where = "#api-launch-known-issues, Oct 19; #plugin-support, #general-technical, Oct 19-22.", code = {  } },
    { n = 34, q = "Beta client won't launch from the news-post link / can't log in", a = "The beta launcher link from the news post is broken, so launch the beta from the docs link instead. Return to live by closing the game and launcher, then relaunching normally.", freq = "Several.", section = "F. Cheats and the dev environment", where = "#plugin-support, #general-technical, Oct 19-20.", code = {  } },
    { n = 35, q = "Game crashes after installing/updating plugins (Oct 21)", a = "Jagex reverted a hotfix on Oct 21. The fix, also for installed plugins that vanish from the hub: close the game, delete every numbered folder (for example 6398181) in C:\\ProgramData\\Jagex\\RuneScape\\plugins, then reinstall your plugins. This uninstalls them but keeps saved settings. On Mac or Linux use the plugins folder in your Jagex cache.", freq = "Often.", section = "G. Crashes and known issues", where = "#api-launch-known-issues, Oct 21; #plugin-support, Oct 21. Updated Oct 23 (#plugin-support, staff reply; the user confirmed it worked).", code = {  } },
    { n = 36, q = "Tile Markers: preset limits and crashes", a = "The limit is 200 highlighted tiles in total; staff say a higher limit is already in a version that is not out yet. Import strings also have a size cap, so split big imports into smaller chunks. The shapes API adds client memory over time. A crash from some preset names (the img text tag) was fixed on Oct 21.", freq = "Often (5+).", section = "G. Crashes and known issues", where = "#plugin-support, Oct 19-20; #api-launch-known-issues, Oct 19. Updated Oct 21.", code = {  } },
    { n = 37, q = "FPS loss and lag with plugins (e.g. Entity Hider, MES)", a = "Known issue: \"some plugins are causing FPS to decrease\" and a hotfix was planned. Debug with displayfps, with and without the plugin and with and without players hidden. In one case hiding entities with Entity Hider fixed the lag from MES.", freq = "Several.", section = "G. Crashes and known issues", where = "#api-launch-known-issues, Oct 20; #plugin-support, Oct 19.", code = {  } },
    { n = 38, q = "MiniMenu / left-click problems, Menu Entry Swapper limits", a = "Known issue: \"several left-click issues with the MiniMenu\". The MES restrictions are an API restriction (see #24).", freq = "Several.", section = "G. Crashes and known issues", where = "#api-launch-known-issues, Oct 19-20.", code = {  } },
    { n = 39, q = "Debug Menu plugin sent hit commands to every NPC", a = "Developer acknowledged an old bug and pushed a fix. No workaround posted.", freq = "Once.", section = "G. Crashes and known issues", where = "#plugin-support, Oct 21.", code = {  } },
    { n = 40, q = "Where's plugin X? Mobile? Release cadence?", a = "Plugins such as Clue Trainer and Ground Items were in moderation. Plugins are not on mobile yet, and new plugins come out in batches with no fixed schedule. Requests answered since: equipment setups are planned in the Bank Utils plugin (in development-resources, compatible with the PVME preset maker); a sound for a specific drop can be set up with the Watchdog plugin; Quest Helper cannot replay Broken Home yet, but restarting the quest updates the log and the developers know about the request.", freq = "Often.", section = "G. Crashes and known issues", where = "#faq, Oct 19. Updated Oct 22 (community answers).", code = {  } },
}
